for name,F in [(\"horizontal\",f),(\"vertical\",g)]:
 for n in range(1,15):
  for j in range(2*n+1):
   for s in range(1,n):
    for q in range(n+1):
     for r in range(q+1,n+1):
      lhs=F(n,j,s-1,q)*F(n,j,s+1,r)+F(n,j,s-1,r)*F(n,j,s+1,q);rhs=2*F(n,j,s,q)*F(n,j,s,r)
      if lhs>rhs and name not in out:out[name]=[n,j,s,q,r,lhs,rhs]
print(json.dumps(out))'"

